    if (chord < 1e-9 && d1 + d2 < tol) { out.push([p3[0], p3[1]]); return; }
    const mid = (a, b) => [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
    const a = mid(p0, p1), b = mid(p1, p2), c = mid(p2, p3);
    const d = mid(a, b), e = mid(b, c), f = mid(d, e);
