    const align = t.align || 'left';
    const lineW = ctx.measureText(line).width;
    let x0 = 0;
    if (align === 'center') x0 = ((n.w || 0) - lineW) / 2;
    else if (align === 'right') x0 = (n.w || 0) - lineW;
    const target = localX - x0;
    if (target <= 0) return prefix;
