      if (!p) continue;
      if (/^\s+$/.test(p)) {
        if (words.length) words[words.length - 1].space = (words[words.length - 1].space || 0) + measureW(ctx, p);
      } else words.push({ text: p, w: measureW(ctx, p), space: 0 });
